const items = [
  { id: 'dom', title: 'Review the DOM guide', done: false },
  { id: 'events', title: 'Read about event bubbling', done: true },
  { id: 'state', title: 'Practise immutable updates', done: false },
];
const list = document.querySelector('#reading-list');
const summary = document.querySelector('#summary');

// The number is captured once, so it becomes stale after a checkbox changes.
const completedCount = items.filter((item) => item.done).length;

function render() {
  summary.textContent = `${completedCount} of ${items.length} readings complete`;
  list.replaceChildren(...items.map((item) => {
    const row = document.createElement('li');
    row.className = `reading-item${item.done ? ' is-complete' : ''}`;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = `reading-${item.id}`;
    checkbox.checked = item.done;
    const label = document.createElement('label');
    label.htmlFor = checkbox.id;
    label.textContent = item.title;
    checkbox.addEventListener('change', () => {
      // This mutates the source object. Replace it with an immutable update.
      item.done = checkbox.checked;
      render();
    });
    row.append(checkbox, label);
    return row;
  }));
}

render();

