const queue = document.querySelector('#queue');
const status = document.querySelector('#queue-status');
let nextReading = 1;

function updateCount(message) {
  status.textContent = `${message} ${queue.children.length} reading${queue.children.length === 1 ? '' : 's'} remain.`;
}

// Bug: each remove button updates the status here...
function attachRemoveHandler(button) {
  button.addEventListener('click', () => updateCount('Removing a reading.'));
}

queue.querySelectorAll('[data-remove]').forEach(attachRemoveHandler);

// ...and the same click bubbles here, so the action is handled twice.
queue.addEventListener('click', (event) => {
  const button = event.target.closest('[data-remove]');
  if (!button || !queue.contains(button)) return;
  button.closest('li').remove();
  updateCount('Removed.');
});

document.querySelector('#add-item').addEventListener('click', () => {
  const item = document.createElement('li');
  const label = document.createElement('span');
  label.textContent = `New reading ${nextReading++}`;
  const button = document.createElement('button');
  button.type = 'button';
