const tabs = [...document.querySelectorAll('[role=tab]')];
const panels = tabs.map((tab) => document.querySelector(`#${tab.getAttribute('aria-controls')}`));

function activateTab(index, moveFocus = false) {
  tabs.forEach((tab, tabIndex) => {
    const selected = tabIndex === index;
    tab.setAttribute('aria-selected', String(selected));
    tab.tabIndex = selected ? 0 : -1;
    panels[tabIndex].hidden = !selected;
  });
  if (moveFocus) tabs[index].focus();
}

// Bug: all tabs start in the Tab order, and arrow keys do not move selection.
// Add roving tabindex and keep keyboard focus and the visible panel synchronized.
tabs.forEach((tab, index) => {
  tab.addEventListener('click', () => activateTab(index));
});

