const catalog = [
  { title: 'Array traversal', terms: 'arrays loops iteration' },
  { title: 'Array transformations', terms: 'arrays map filter reduce' },
  { title: 'Map lookups', terms: 'maps keys values lookup' },
  { title: 'Map and set tradeoffs', terms: 'maps sets collections' },
];
const form = document.querySelector('#search-form');
const queryInput = document.querySelector('#query');
const status = document.querySelector('#search-status');
const results = document.querySelector('#results');

function searchCatalog(query) {
  const normalized = query.toLocaleLowerCase();
  const matches = catalog.filter((item) => `${item.title} ${item.terms}`.toLocaleLowerCase().includes(normalized));
  const delay = normalized.includes('array') ? 700 : 120;
  return new Promise((resolve) => window.setTimeout(() => resolve(matches), delay));
}

function render(items) {
  results.replaceChildren(...items.map((item) => {
    const row = document.createElement('li');
    row.textContent = item.title;
    return row;
  }));
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  const query = queryInput.value.trim();
  if (!query) return;
  status.textContent = `Searching for ${query}…`;
  const items = await searchCatalog(query);
  // Bug: an older request can finish later and overwrite newer results.
  render(items);
  status.textContent = `${items.length} result${items.length === 1 ? '' : 's'} for ${query}.`;
});

